/** Umpire profile from pybaseballstats (accuracy%, zone size, pitcher/batter-friendly) */
export const fetchUmpireProfile = (umpireName) => {
  if (!umpireName) return Promise.resolve(null);
  // Try static pre-generated data first, fall back to live backend
  const slug = umpireName.toLowerCase().replace(/\s+/g, "_");
  return staticFetch(`umpires/${slug}.json`).catch(() =>
    // Live backend call
    axios.get(`/api/umpire/${encodeURIComponent(umpireName)}`).then((r) => r.data).catch(() => null)
  );
};

// ---- Live data (MLB Stats API, called directly from browser) ----
export const fetchTodayGame = async (teamId) => {
  const today = new Date();
  const endDate = new Date(today);
  endDate.setDate(endDate.getDate() + 14);

  const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;

  try {
    // Check today first
    const todayResp = await mlbApi.get("/schedule", {
      params: {
        sportId: 1, teamId, date: fmt(today),
        hydrate: "team,linescore,probablePitcher,officials,venue(location)", gameType: "R",
      },
    });

    const todayGames = todayResp.data.dates?.[0]?.games || [];

    // Live or scheduled game today
    const liveOrScheduled = todayGames.find((g) =>
      ["In Progress", "Scheduled", "Pre-Game", "Warmup", "Delayed Start", "Delayed", "Suspended"].includes(g.status?.detailedState)
    );
    if (liveOrScheduled) return formatGame(liveOrScheduled, true);

    // Final game today - also find next game
    const finalGame = todayGames.find((g) => g.status?.detailedState === "Final");

    // Get upcoming games
    const futureResp = await mlbApi.get("/schedule", {
      params: {
        sportId: 1, teamId, startDate: fmt(today), endDate: fmt(endDate),
        hydrate: "team,linescore,probablePitcher,officials,venue(location)", gameType: "R",
      },
    });

    const allDates = futureResp.data.dates || [];
    let nextGame = null;
    for (const dateEntry of allDates) {
      const gameDate = new Date(dateEntry.date + "T00:00:00");
      if (gameDate <= today) continue;
      if (dateEntry.games?.length) {
        nextGame = dateEntry.games[0];
        break;
      }
    }

    if (finalGame) {
      const result = formatGame(finalGame, false);
      result.nextGame = nextGame ? formatGame(nextGame, true) : null;
      return result;
    }

    if (nextGame) return formatGame(nextGame, true);
    return { noGame: true, message: "No games scheduled in the next 14 days." };
  } catch (e) {
    console.error("Failed to fetch game:", e);
    return { noGame: true, message: "Unable to load game data." };
  }
};

// Fetch hot/cold players for a team (last 7 games)
export const fetchHotColdPlayers = async (teamId) => {
  try {
    const roster = await fetchRoster(teamId);
    const batters = roster.filter((p) => p.position.type !== "Pitcher");
    const results = await Promise.all(
      batters.map(async (p) => {
        try {
          const resp = await mlbApi.get(`/people/${p.id}/stats`, {
            params: { stats: "lastXGames", group: "hitting", gameType: "R", limit: 7 },
          });
          const s = resp.data?.stats?.[0]?.splits?.[0]?.stat || {};
          const ab = s.atBats || 0;
          if (ab < 5) return null;
          return {
            id: p.id,
            fullName: p.fullName,
            position: p.position.abbreviation,
            avg: s.avg || ".000",
            ops: s.ops || ".000",
            hits: s.hits || 0,
            hr: s.homeRuns || 0,
            ab,
          };
        } catch { return null; }
      })
    );
    const valid = results.filter(Boolean);
    const hot = [...valid].sort((a, b) => parseFloat(b.ops) - parseFloat(a.ops)).slice(0, 3);
    const cold = [...valid].sort((a, b) => parseFloat(a.ops) - parseFloat(b.ops)).slice(0, 3);
    return { hot, cold };
  } catch {
    return { hot: [], cold: [] };
  }
};

// Fetch bullpen availability for a team (excludes starters)
export const fetchBullpenAvailability = async (teamId, starterIds = []) => {
  try {
    const roster = await fetchRoster(teamId);
    const pitchers = roster.filter((p) => p.position.type === "Pitcher" && !starterIds.includes(p.id));
    const season = new Date().getFullYear();
    const today = new Date();

    const results = await Promise.all(
      pitchers.map(async (p) => {
        try {
          // Fetch current + prior season stats and game log
          const [curResp, prevResp, logResp] = await Promise.all([
            mlbApi.get(`/people/${p.id}/stats`, { params: { stats: "season", group: "pitching", season } }),
            mlbApi.get(`/people/${p.id}/stats`, { params: { stats: "season", group: "pitching", season: season - 1 } }),
            mlbApi.get(`/people/${p.id}/stats`, { params: { stats: "gameLog", group: "pitching", gameType: "R", season, limit: 3 } }),
          ]);

          // Skip starters (GS > 50% of games) — check current season first, fall back to prior
          const curStat = curResp.data?.stats?.[0]?.splits?.[0]?.stat || {};
          const prevStat = prevResp.data?.stats?.[0]?.splits?.[0]?.stat || {};
          const stat = (curStat.gamesPlayed || 0) > 0 ? curStat : prevStat;
          const gp = stat.gamesPlayed || 0;
          const gs = stat.gamesStarted || 0;
          if (gp > 0 && gs / gp > 0.5) return null;

          const splits = logResp.data?.stats?.[0]?.splits || [];
          let lastGameDate = null;
          let daysRest = 99;
          let recentPitches = 0;
          let recentGames = 0;

          for (const s of splits.slice(0, 3)) {
            const gDate = new Date(s.date);
            const daysDiff = Math.floor((today - gDate) / (1000 * 60 * 60 * 24));
            if (!lastGameDate) {
              lastGameDate = s.date;
              daysRest = daysDiff;
            }
            if (daysDiff <= 3) {
              recentPitches += s.stat?.numberOfPitches || 0;
              recentGames++;
            }
          }

          let status = "available";
          if (daysRest === 0) status = "unavailable";
          else if (daysRest === 1 && recentPitches > 25) status = "limited";
          else if (recentGames >= 3 && daysRest <= 1) status = "unavailable";

          return {
            id: p.id,
            fullName: p.fullName,
            daysRest,
            recentPitches,
            status,
            lastGameDate,
          };
        } catch {
          return null;
        }
      })
    );

    return results.filter(Boolean).sort((a, b) => a.daysRest - b.daysRest);
  } catch {
    return [];
  }
};

// Fetch injured list for a team (40-man roster IL players)
export const fetchTeamInjuries = async (teamId) => {
  try {
    const season = new Date().getFullYear();
    const resp = await mlbApi.get(`/teams/${teamId}/roster`, {
      params: { rosterType: "40Man", season },
    });
    return (resp.data?.roster || [])
      .filter((r) => r.status?.description?.toLowerCase().includes("injured"))
      .map((r) => ({
        id: r.person?.id,
        fullName: r.person?.fullName || "",
        position: r.position?.abbreviation || "",
        ilType: r.status?.description || "",
      }));
  } catch {
    return [];
  }
};

