// All MLB games today (scoreboard)
export const fetchAllGamesToday = async (dateStr) => {
  try {
    const dateParam = dateStr || (() => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`; })();
    const resp = await mlbApi.get("/schedule", {
      params: {
        sportId: 1, date: dateParam,
        hydrate: "team,linescore,probablePitcher,weather,venue(location),decisions", gameType: "R",
      },
    });
    const games = [];
    for (const dateEntry of resp.data?.dates || []) {
      for (const g of dateEntry.games || []) {
        const away = g.teams?.away || {};
        const home = g.teams?.home || {};
        const at = away.team || {};
        const ht = home.team || {};
        const ls = g.linescore || {};
        const w = g.weather || {};
        // Extract inning-by-inning linescore
        const innings = (ls.innings || []).map((inn) => ({
          num: inn.num,
          away: inn.away?.runs ?? "",
          home: inn.home?.runs ?? "",
        }));
        const lsTeams = ls.teams || {};
        const linescore = innings.length ? {
          innings,
          away: { runs: lsTeams.away?.runs ?? 0, hits: lsTeams.away?.hits ?? 0, errors: lsTeams.away?.errors ?? 0 },
          home: { runs: lsTeams.home?.runs ?? 0, hits: lsTeams.home?.hits ?? 0, errors: lsTeams.home?.errors ?? 0 },
        } : null;

        games.push({
          gamePk: g.gamePk,
          gameDate: g.gameDate || "",
          status: g.status?.detailedState || "",
          inning: ls.currentInning || null,
          inningHalf: ls.inningHalf || "",
          venue: g.venue?.name || "",
          venueLocation: g.venue?.location ? `${g.venue.location.city}, ${g.venue.location.stateAbbrev}` : "",
          weather: w.temp ? { temp: w.temp, condition: w.condition || "", wind: w.wind || "" } : null,
          linescore,
          away: {
            id: at.id, name: at.name || "", abbreviation: at.abbreviation || "",
            score: away.score, wins: away.leagueRecord?.wins, losses: away.leagueRecord?.losses,
            probablePitcher: extractPitcher(away.probablePitcher),
            logoUrl: `https://www.mlbstatic.com/team-logos/team-cap-on-dark/${at.id}.svg`,
          },
          home: {
            id: ht.id, name: ht.name || "", abbreviation: ht.abbreviation || "",
            score: home.score, wins: home.leagueRecord?.wins, losses: home.leagueRecord?.losses,
            probablePitcher: extractPitcher(home.probablePitcher),
            logoUrl: `https://www.mlbstatic.com/team-logos/team-cap-on-dark/${ht.id}.svg`,
          },
          decisions: g.decisions ? {
            winner: g.decisions.winner ? { id: g.decisions.winner.id, name: g.decisions.winner.fullName } : null,
            loser: g.decisions.loser ? { id: g.decisions.loser.id, name: g.decisions.loser.fullName } : null,
            save: g.decisions.save ? { id: g.decisions.save.id, name: g.decisions.save.fullName } : null,
          } : null,
        });
      }
    }
    return games;
  } catch {
    return [];
  }
};

// Box score + at-bat details for expanded game view
function formatAtBatShort(event, desc, hrDistance) {
  const d = desc.toLowerCase();
  const dir = d.match(/to (left|right|center|left-center|right-center)\s*(field)?/)?.[1] || "";
  const dirStr = dir ? ` to ${dir} field` : "";

  switch (event) {
    case "Strikeout":
      return d.includes("looking") || d.includes("called") ? "Strikeout looking" : "Strikeout swinging";
    case "Single": return `Single${dirStr}`;
    case "Double": return `Double${dirStr}`;
    case "Triple": return `Triple${dirStr}`;
    case "Home Run": return `Home run${dirStr}${hrDistance ? ` (${hrDistance} ft)` : ""}`;
    case "Walk": return "Walk";
    case "Intent Walk": return "Intentional walk";
    case "Hit By Pitch": return "Hit by pitch";
    case "Flyout": return `Flyout${dirStr}`;
    case "Lineout": return `Lineout${dirStr}`;
    case "Pop Out": return `Pop out${dirStr}`;
    case "Groundout": return `Groundout${d.includes("shortstop") ? " to short" : d.includes("second") ? " to second" : d.includes("third") ? " to third" : d.includes("first") ? " to first" : d.includes("pitcher") ? " to pitcher" : ""}`;
    case "Grounded Into DP": return "Grounded into double play";
    case "Fielders Choice": return "Fielder's choice";
    case "Sac Fly": return `Sac fly${dirStr}`;
    case "Sac Bunt": return "Sac bunt";
    case "Force Out": return "Force out";
    case "Field Error": return "Reached on error";
    default: return event || "Unknown";
  }
}

export const fetchGameDetail = async (gamePk) => {
  try {
    const [boxResp, pbpResp] = await Promise.all([
      mlbApi.get(`/game/${gamePk}/boxscore`),
      mlbApi.get(`/game/${gamePk}/playByPlay`),
    ]);

    const allPlays = pbpResp.data?.allPlays || [];

    // Build at-bats grouped by batter ID
    const atBatsByBatter = {};
    for (const play of allPlays) {
      const batterId = play.matchup?.batter?.id;
      if (!batterId || !play.result?.event) continue;
      if (!atBatsByBatter[batterId]) atBatsByBatter[batterId] = [];
      let hrDistance = null;
      if (play.result.event === "Home Run") {
        const hitEvent = (play.playEvents || []).find((e) => e.hitData?.totalDistance);
        if (hitEvent) hrDistance = Math.round(hitEvent.hitData.totalDistance);
      }
      atBatsByBatter[batterId].push({
        inning: play.about?.inning || 0,
        halfInning: play.about?.halfInning || "",
        event: play.result.event,
        description: play.result.description || "",
        shortDesc: formatAtBatShort(play.result.event, play.result.description || "", hrDistance),
        rbi: play.result.rbi ?? 0,
        isScoring: play.about?.isScoringPlay || false,
        hrDistance,
      });
    }

    // Extract scoring plays
    const scoringPlays = allPlays
      .filter((p) => p.about?.isScoringPlay)
      .map((p) => {
        let hrDistance = null;
        const event = p.result?.event || "";
        if (event === "Home Run") {
          const hitEvent = (p.playEvents || []).find((e) => e.hitData?.totalDistance);
          if (hitEvent) hrDistance = Math.round(hitEvent.hitData.totalDistance);
        }
        return {
          inning: p.about?.inning || 0,
          halfInning: p.about?.halfInning || "",
          description: p.result?.description || "",
          awayScore: p.result?.awayScore ?? 0,
          homeScore: p.result?.homeScore ?? 0,
          rbi: p.result?.rbi ?? 0,
          event,
          hrDistance,
        };
      });

    // Parse box score for both teams
    const parseTeam = (teamData) => {
      const batters = (teamData?.batters || []).map((id) => {
        const p = teamData.players?.[`ID${id}`];
        if (!p) return null;
        const s = p.stats?.batting || {};
        const isP = p.position?.abbreviation === "P";
        // Skip pitchers with no at-bats
        if (isP && !s.atBats) return null;
        return {
          id,
          name: p.person?.fullName || "",
          position: p.position?.abbreviation || "",
          battingOrder: p.battingOrder || "",
          stats: {
            ab: s.atBats ?? 0, r: s.runs ?? 0, h: s.hits ?? 0,
            rbi: s.rbi ?? 0, bb: s.baseOnBalls ?? 0, k: s.strikeOuts ?? 0,
            hr: s.homeRuns ?? 0, avg: s.avg || "",
          },
          atBats: atBatsByBatter[id] || [],
        };
      }).filter(Boolean);

      const pitchers = (teamData?.pitchers || []).map((id) => {
        const p = teamData.players?.[`ID${id}`];
        if (!p) return null;
        const s = p.stats?.pitching || {};
        return {
          id,
          name: p.person?.fullName || "",
          stats: {
            ip: s.inningsPitched ?? "0",
            h: s.hits ?? 0,
            r: s.runs ?? 0,
            er: s.earnedRuns ?? 0,
            bb: s.baseOnBalls ?? 0,
            k: s.strikeOuts ?? 0,
            pitches: s.numberOfPitches ?? 0,
            strikes: s.strikes ?? 0,
          },
          note: s.note || "",
        };
      }).filter(Boolean);

      return { batters, pitchers };
    };

    const box = boxResp.data?.teams || {};
    const away = parseTeam(box.away);
    const home = parseTeam(box.home);
    return {
      away: away.batters,
      home: home.batters,
      awayPitchers: away.pitchers,
      homePitchers: home.pitchers,
      scoringPlays,
    };
  } catch {
    return null;
  }
};



// Pitcher season stats (ERA, W-L) for scoreboard cards
export const fetchPitcherSeasonStats = async (pitcherId) => {
  const year = new Date().getFullYear();
  for (const season of [year, year - 1]) {
    try {
      const resp = await mlbApi.get(`/people/${pitcherId}/stats`, {
        params: { stats: "season", season, group: "pitching" },
      });
      const stat = resp.data?.stats?.[0]?.splits?.[0]?.stat;
      if (stat && (stat.gamesStarted > 0 || stat.gamesPitched > 0)) {
        return {
          era: stat.era || "-.--",
          wins: stat.wins || 0,
          losses: stat.losses || 0,
          saves: stat.saves || 0,
          ip: stat.inningsPitched || "0",
          so: stat.strikeOuts || 0,
          season,
        };
      }
    } catch (e) { console.warn("fetch failed:", e.message); }
  }
  return null;
};

// 3. Transaction feed (roster moves, IL, trades)
export const fetchTransactions = async (teamId) => {
  try {
    const end = new Date();
    const start = new Date();
    start.setDate(start.getDate() - 30);
    const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
    const resp = await mlbApi.get("/transactions", {
      params: { teamId, startDate: fmt(start), endDate: fmt(end) },
    });
    return (resp.data?.transactions || []).map((t) => ({
      id: t.id,
      date: t.date,
      type: t.typeCode,
      typeDesc: t.typeDesc,
      description: t.description,
      player: t.person ? { id: t.person.id, name: t.person.fullName } : null,
    })).slice(0, 10);
  } catch {
    return [];
  }
};

// 4. Player game log (last 10 games)
export const fetchPlayerGameLog = async (playerId, group = "hitting") => {
  const year = new Date().getFullYear();
  for (const season of [year, year - 1]) {
    try {
      const resp = await mlbApi.get(`/people/${playerId}/stats`, {
        params: { stats: "gameLog", season, group },
      });
      const splits = resp.data?.stats?.[0]?.splits || [];
      if (splits.length) {
        return splits.slice(-10).reverse().map((s) => ({
          date: s.date,
          opponent: s.opponent?.abbreviation || s.opponent?.name?.split(" ").pop() || "",
          isHome: s.isHome,
          isWin: s.isWin,
          stat: s.stat,
        }));
      }
    } catch (e) { console.warn("fetch failed:", e.message); }
  }
  return [];
};

// 5. Win probability for a game
export const fetchWinProbability = async (gamePk) => {
  try {
    const resp = await mlbApi.get(`/game/${gamePk}/winProbability`);
    return (resp.data || []).map((wp) => ({
      atBatIndex: wp.atBatIndex,
      inning: wp.about?.inning || 0,
      halfInning: wp.about?.halfInning || "top",
      homeProb: (wp.homeTeamWinProbability || 0) / 100,
      awayProb: (wp.awayTeamWinProbability || 0) / 100,
      probAdded: (wp.homeTeamWinProbabilityAdded || 0) / 100,
      leverage: wp.leverageIndex,
    }));
  } catch {
    return [];
  }
};

// 8. Team hot/cold players (our team, last 7 days game logs)
export const fetchTeamHotCold = async (teamId) => {
  try {
    const abbr = getTeamAbbr(teamId);
    const roster = await staticFetch(`teams/${abbr}/roster.json`);
    const batters = roster.filter((p) => p.position.type !== "Pitcher");
    const year = new Date().getFullYear();
    const results = [];

    for (const batter of batters.slice(0, 15)) {
      try {
        const resp = await mlbApi.get(`/people/${batter.id}/stats`, {
          params: { stats: "gameLog", season: year, group: "hitting" },
        });
        const splits = resp.data?.stats?.[0]?.splits || [];
        const last7 = splits.slice(-7);
        if (last7.length < 3) continue;

        let ab = 0, hits = 0, hr = 0, rbi = 0, bb = 0, hbp = 0, sf = 0, doubles = 0, triples = 0;
        for (const g of last7) {
          const s = g.stat;
          ab += s.atBats || 0;
          hits += s.hits || 0;
          hr += s.homeRuns || 0;
          rbi += s.rbi || 0;
          bb += s.baseOnBalls || 0;
          hbp += s.hitByPitch || 0;
          sf += s.sacFlies || 0;
          doubles += s.doubles || 0;
          triples += s.triples || 0;
        }
        if (ab < 10) continue;
        const avg = hits / ab;
        const pa = ab + bb + hbp + sf;
        const obp = pa > 0 ? (hits + bb + hbp) / pa : 0;
        const singles = hits - doubles - triples - hr;
        const tb = singles + doubles * 2 + triples * 3 + hr * 4;
        const slg = ab > 0 ? tb / ab : 0;
        const ops = Math.round((obp + slg) * 1000) / 1000;

        results.push({
          id: batter.id,
          name: batter.fullName,
          position: batter.position.abbreviation,
          games: last7.length, ab, hits, hr, rbi, ops,
          avg: Math.round(avg * 1000) / 1000,
          photoUrl: batter.photoUrl,
          isHot: avg >= .300,
          isCold: avg < .150,
        });
      } catch (e) { console.warn("fetch failed:", e.message); }
    }

    results.sort((a, b) => b.avg - a.avg);
    return {
      hot: results.filter((r) => r.isHot).slice(0, 5),
      cold: results.filter((r) => r.isCold).slice(0, 3),
    };
  } catch {
    return { hot: [], cold: [] };
  }
};

// 9. League leaders
export const fetchLeagueLeaders = async () => {
  try {
    const year = new Date().getFullYear();
    const hittingCats = ["homeRuns", "battingAverage", "runsBattedIn", "onBasePlusSlugging", "stolenBases", "hits"];
    const pitchingCats = ["earnedRunAverage", "strikeouts", "wins", "saves", "whip"];
    const hitting = {};
    const pitching = {};

    const fetchCat = async (cat, group, dest) => {
      try {
        const resp = await mlbApi.get("/stats/leaders", {
          params: { leaderCategories: cat, season: year, sportId: 1, limit: 5, statGroup: group },
        });
        const leaders = resp.data?.leagueLeaders?.[0]?.leaders || [];
        dest[cat] = leaders.map((l) => ({
          rank: l.rank,
          value: l.value,
          player: { id: l.person?.id, name: l.person?.fullName },
          team: l.team?.abbreviation || "",
          teamId: l.team?.id,
        }));
      } catch (e) { console.warn("fetch failed:", e.message); }
    };

    // Fetch longest HRs from Baseball Savant
    const fetchLongestHR = async () => {
      try {
        const resp = await axios.get(`https://baseballsavant.mlb.com/leaderboard/statcast?type=batter&year=${year}&position=&team=&min=10&sort=11&sortDir=desc&csv=true`, { timeout: 10000 });
        const text = resp.data.replace(/^\ufeff/, "");
        const lines = text.split("\n");
        const headers = lines[0].split(",").map((h) => h.replace(/"/g, "").trim());
        const nameIdx = 0;
        const distIdx = headers.indexOf("max_distance");
        if (distIdx === -1) return;
        const rows = lines.slice(1).filter((l) => l.trim()).map((line) => {
          const cols = line.match(/(".*?"|[^,]+)/g)?.map((c) => c.replace(/"/g, "").trim()) || [];
          return { name: cols[nameIdx], distance: parseInt(cols[distIdx]) || 0 };
        });
        rows.sort((a, b) => b.distance - a.distance);
        hitting.longestHR = rows.slice(0, 5).map((r, i) => ({
          rank: i + 1,
          value: String(r.distance),
          player: { name: r.name?.split(", ").reverse().join(" ") || "Unknown" },
          team: "",
          teamId: null,
        }));
      } catch (e) { console.warn("Longest HR fetch failed:", e.message); }
    };

    await Promise.all([
      ...hittingCats.map((cat) => fetchCat(cat, "hitting", hitting)),
      ...pitchingCats.map((cat) => fetchCat(cat, "pitching", pitching)),
      fetchLongestHR(),
    ]);
    return { hitting, pitching };
  } catch {
    return { hitting: {}, pitching: {} };
  }
};

// 10. Upcoming series (next 4 games with probable pitchers)
export const fetchUpcomingSeries = async (teamId) => {
  try {
    const today = new Date();
    const end = new Date();
    end.setDate(end.getDate() + 10);
    const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;

    const resp = await mlbApi.get("/schedule", {
      params: {
        sportId: 1, teamId,
        startDate: fmt(today), endDate: fmt(end),
        hydrate: "team,probablePitcher", gameType: "R",
      },
    });

    const games = [];
    for (const dateEntry of resp.data?.dates || []) {
      for (const g of dateEntry.games || []) {
        const status = g.status?.detailedState || "";
        if (["Final", "In Progress", "Warmup", "Delayed Start", "Delayed", "Suspended", "Game Over"].includes(status)) continue;
        const away = g.teams?.away || {};
        const home = g.teams?.home || {};
        games.push({
          gamePk: g.gamePk,
          gameDate: g.gameDate,
          venue: g.venue?.name || "",
          away: {
            id: away.team?.id, abbreviation: away.team?.abbreviation || "",
            probablePitcher: extractPitcher(away.probablePitcher),
            logoUrl: `https://www.mlbstatic.com/team-logos/team-cap-on-dark/${away.team?.id}.svg`,
          },
          home: {
            id: home.team?.id, abbreviation: home.team?.abbreviation || "",
            probablePitcher: extractPitcher(home.probablePitcher),
            logoUrl: `https://www.mlbstatic.com/team-logos/team-cap-on-dark/${home.team?.id}.svg`,
          },
        });
        if (games.length >= 4) break;
      }
      if (games.length >= 4) break;
    }
    return games;
  } catch {
    return [];
  }
};

// ---- Helpers ----
function formatGame(g, isNext) {
  const away = g.teams?.away || {};
  const home = g.teams?.home || {};
  const at = away.team || {};
  const ht = home.team || {};

  // Extract home plate umpire from officials list
  const officials = g.officials || [];
  const hpUmpire = officials.find((o) =>
    o.officialType === "Home Plate" || o.officialType === "HP"
  );
  const umpireName = hpUmpire?.official?.fullName || null;

  return {
    gamePk: g.gamePk,
    gameDate: g.gameDate || "",
    status: g.status?.detailedState || "",
    isNextGame: isNext,
    venue: { id: g.venue?.id, name: g.venue?.name || "" },
    venueLocation: g.venue?.location ? `${g.venue.location.city}, ${g.venue.location.stateAbbrev}` : "",
    umpireName,
    away: {
      id: at.id, name: at.name || "", abbreviation: at.abbreviation || "",
      score: away.score,
      wins: away.leagueRecord?.wins, losses: away.leagueRecord?.losses,
      probablePitcher: extractPitcher(away.probablePitcher),
      logoUrl: `https://www.mlbstatic.com/team-logos/team-cap-on-dark/${at.id}.svg`,
    },
    home: {
      id: ht.id, name: ht.name || "", abbreviation: ht.abbreviation || "",
      score: home.score,
      wins: home.leagueRecord?.wins, losses: home.leagueRecord?.losses,
      probablePitcher: extractPitcher(home.probablePitcher),
      logoUrl: `https://www.mlbstatic.com/team-logos/team-cap-on-dark/${ht.id}.svg`,
    },
  };
}

function extractPitcher(p) {
  if (!p) return null;
  return {
    id: p.id,
    fullName: p.fullName || "",
    photoUrl: `https://img.mlbstatic.com/mlb-photos/image/upload/d_people:generic:headshot:67:current.png/w_213,q_auto:best/v1/people/${p.id}/headshot/67/current`,
  };
}
